def dedupe(items):
    """Return items with duplicates removed, first occurrence order preserved.

    Items are not guaranteed to be hashable. Must handle large inputs.
    """
    seen = set()
    unhashable = []
    out = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            if item in unhashable:
                continue
            unhashable.append(item)
        out.append(item)
    return out
